	@Test
	void arbitrarySplitsShareAnIdWithoutAlternativeSearches(@TempDir File directory) throws Exception {
		try (ObservedValueStore store = new ObservedValueStore(directory)) {
			store.startTransaction(true);
			long id = store.storeValue(store.createIRI("urn:canonical:", "people/person"));
			store.commit();
			assertEquals(7, store.getFormat().getVersion());
			String lexical = "urn:canonical:people/person";
			for (int split = 0; split <= lexical.length(); split++) {
				store.clearCaches();
				Value value = store.createIRI(lexical.substring(0, split), lexical.substring(split));
				assertEquals(id, store.getId(value), "lookup split " + split);
				store.startTransaction(true);
				assertEquals(id, store.storeValue(value), "write split " + split);
				store.commit();
			}
			assertEquals(lexical, store.getValue(id).stringValue());
			assertNoAlternativeSearch(store);
		}
	}

