	@ParameterizedTest
	@ValueSource(strings = { "https://example.org/a#b/c:d#tail", "https://example.org/a/b:c",
			"urn:example:leaf", "urn:example:", "https://example.org/", "https://example.org/#",
			"https://example.org/æ/雪#🦊/leaf", "urn:exact:e\u0301", "urn:exact:é", "urn:exact:%2f" })
	void everySplitPreservesLexicalIdentityAndSnapshotLookup(String lexical, @TempDir File directory)
			throws Exception {
		long id;
		try (ObservedValueStore store = new ObservedValueStore(directory)) {
			id = persist(store, store.createIRI(lexical, ""));
			for (int split = 0; split <= lexical.length(); split++) {
				store.clearCaches();
				IRI requested = store.createIRI(lexical.substring(0, split), lexical.substring(split));
				assertEquals(id, store.getId(requested), "split " + split);
				try (ValueStore.ReadSnapshotReservation reservation = store.reserveReadSnapshot();
						ValueStore.ReadSnapshot snapshot = reservation.start()) {
					assertEquals(id, store.getId(snapshot, requested), "snapshot split " + split);
					assertEquals(LmdbValue.UNKNOWN_ID,
							store.getId(snapshot, VALUES.createIRI(lexical + "-absent")));
				}
			}
			assertNoAlternativeSearch(store);
		}
		try (ObservedValueStore reopened = new ObservedValueStore(directory)) {
			assertEquals(id, reopened.getId(VALUES.createIRI(lexical)));
			assertEquals(lexical, reopened.getValue(id).stringValue());
			assertEquals(7, reopened.getFormat().getVersion());
			assertNoAlternativeSearch(reopened);
		}
	}

	@ParameterizedTest
	@EnumSource(WritePath.class)
	void scalarBatchAndFreshPathsAgreeOnNestedDependencies(WritePath path, @TempDir File directory) throws Exception {
		Value[] requested;
		long[] ids;
		try (ObservedValueStore store = new ObservedValueStore(directory)) {
			IRI first = store.createIRI("https://example.org/", "shared/a#long:local/雪🦊");
			IRI duplicate = store.createIRI(first.stringValue(), "");
			IRI predicate = store.createIRI("urn:canonical:", "predicates/p");
			IRI datatype = store.createIRI("urn:", "canonical:datatypes/type");
			Literal literal = VALUES.createLiteral("lexical value", datatype);
			TripleTerm inner = VALUES.createTripleTerm(first, predicate, literal);
			TripleTerm outer = VALUES.createTripleTerm(first, predicate, inner);
			Value[] inputs = { first, duplicate, predicate, datatype, literal, inner, outer,
					store.createIRI("https://example.org/", "n/" + "long".repeat(60)) };
			requested = new Value[inputs.length];
			for (int i = 0; i < inputs.length; i++) {
				requested[i] = lexicalCopy(inputs[i]);
			}
			ids = write(store, inputs, path);
			assertEquals(ids[0], ids[1], "different splits of one lexical IRI");
			store.clearCaches();
			try (ValueStore.ReadSnapshotReservation reservation = store.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start()) {
				for (int i = 0; i < inputs.length; i++) {
					assertEquals(ids[i], store.getId(requested[i]), "ordinary lookup " + i);
					assertEquals(ids[i], store.getId(snapshot, requested[i]), "snapshot lookup " + i);
					assertEquals(requested[i], store.getValue(ids[i]), "reconstruction " + i);
				}
			}
			long[] repeated = write(store, requested, WritePath.BATCH);
			for (int i = 0; i < ids.length; i++) {
				assertEquals(ids[i], repeated[i], "batch reinsertion " + i);
			}
			assertNoAlternativeSearch(store);
		}
		try (ObservedValueStore reopened = new ObservedValueStore(directory)) {
			for (int i = 0; i < ids.length; i++) {
				assertEquals(ids[i], reopened.getId(requested[i]), "reopened lookup " + i);
				assertEquals(requested[i], reopened.getValue(ids[i]), "reopened reconstruction " + i);
			}
			assertNoAlternativeSearch(reopened);
		}
	}

