	@Test
	void rollbackAndReusedIdsRetainTheCanonicalInvariant(@TempDir File directory) throws Exception {
		try (ObservedValueStore store = new ObservedValueStore(directory)) {
			IRI original = VALUES.createIRI("urn:canonical:reuse/original");
			long id = persist(store, original);
			store.startTransaction(true);
			store.gcIds(Set.of(id), new HashSet<>());
			store.commit();
			// No Sail coordinator owns this standalone dictionary.
			store.completeStoreInitialization(unusedCandidatesWithoutStatementReferences -> {
				// This standalone dictionary has no external statement references.
			});
			store.reclaimPersistedUnusedIdsBatch(4096);
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(original));
			IRI replacement = store.createIRI("urn:", "canonical:reuse/replacement");
			store.startTransaction(true);
			long provisional = store.storeValue(replacement);
			assertEquals(id, provisional, "exercise an actually reused ID");
			store.rollback();
			store.clearCaches();
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(lexicalCopy(replacement)));
			assertEquals(id, persist(store, lexicalCopy(replacement)));
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(original));
			assertNotEquals(original.stringValue(), store.getValue(id).stringValue());
			assertNoAlternativeSearch(store);
		}
	}

	@Test
	void canonicalSnapshotMemoPreservesMutationConcurrencyAndCloseBoundaries(@TempDir File directory) throws Exception {
		try (ObservedValueStore store = new ObservedValueStore(directory)) {
			String first = "urn:canonical:snapshot/first";
			String second = "urn:canonical:snapshot/second";
			long firstId = persist(store, VALUES.createIRI(first));
			long secondId = persist(store, VALUES.createIRI(second));
			try (ValueStore.ReadSnapshotReservation reservation = store.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start();
					var readers = Executors.newFixedThreadPool(4)) {
				AtomicReference<String> lexical = new AtomicReference<>(first);
				AtomicBoolean closeOnRead = new AtomicBoolean();
				IRI input = new AbstractIRI() {
					@Override
					public String stringValue() {
						assertFalse(Thread.holdsLock(snapshot.txnRef()),
								"Caller payload stays outside the native monitor");
						if (closeOnRead.get()) {
							snapshot.close();
						}
						return lexical.get();
					}

					@Override
					public String getNamespace() {
						throw new AssertionError("Canonical snapshots must capture only the lexical IRI");
					}

					@Override
					public String getLocalName() {
						throw new AssertionError("Canonical snapshots must capture only the lexical IRI");
					}
				};
				long beforeLookup = store.snapshotIdLookups().dictionaryReads();
				assertEquals(firstId, store.getId(snapshot, input));
				long firstLookups = store.snapshotIdLookups().dictionaryReads();
				assertTrue(firstLookups > beforeLookup, "The cold lookup must read the snapshot dictionary");
				List<Future<?>> lookups = new ArrayList<>();
				for (int thread = 0; thread < 4; thread++) {
					lookups.add(readers.submit(() -> {
						for (int iteration = 0; iteration < 128; iteration++) {
							assertEquals(firstId, store.getId(snapshot, input));
						}
						return null;
					}));
				}
				for (Future<?> lookup : lookups) {
					lookup.get(10, TimeUnit.SECONDS);
				}
				assertEquals(firstLookups, store.snapshotIdLookups().dictionaryReads(),
						"Concurrent warmed hits must reuse the native result");
				lexical.set(second);
				assertEquals(secondId, store.getId(snapshot, input), "Lexical mutation invalidates a cached identity");
				assertTrue(store.snapshotIdLookups().dictionaryReads() > firstLookups);
				closeOnRead.set(true);
				assertThrows(IOException.class, () -> store.getId(snapshot, input),
						"Reentrant close from a lexical getter cannot publish a stale cached result");
				assertThrows(IOException.class, () -> store.getId(snapshot, VALUES.createIRI(second)));
			}
			assertNoAlternativeSearch(store);
		}
	}

	private static Value lexicalCopy(Value value) {
		if (value instanceof TripleTerm triple) {
			return VALUES.createTripleTerm((Resource) lexicalCopy(triple.getSubject()),
					(IRI) lexicalCopy(triple.getPredicate()), lexicalCopy(triple.getObject()));
		}
		if (value instanceof Literal literal) {
			return VALUES.createLiteral(literal.getLabel(), VALUES.createIRI(literal.getDatatype().stringValue()));
		}
		return VALUES.createIRI(value.stringValue());
	}

	private static long persist(ObservedValueStore store, Value value) throws IOException {
		store.startTransaction(true);
		long id = store.storeValue(value);
		store.commit();
		store.clearCaches();
		return id;
	}

	private static long[] write(ObservedValueStore store, Value[] values, WritePath path) throws IOException {
		store.startTransaction(true);
		long[] ids = new long[values.length];
		switch (path) {
		case SCALAR -> {
			for (int i = 0; i < values.length; i++) {
				ids[i] = store.storeValue(values[i]);
			}
			store.commit();
		}
		case BATCH -> {
			store.storeValues(values, ids, values.length);
			store.commit();
		}
		case PREPARED, ASSIGNED -> {
			ValueStore.FreshValueSession session = store.startFreshValueSessionIfEmpty();
			assertNotNull(session);
			store.reservePreparedValueClosureCapacity(session, values);
			ValueStore.PreparedValueBatch publication;
			if (path == WritePath.PREPARED) {
				publication = store.prepareFreshValues(session, values);
				store.persistPreparedValues(publication);
			} else {
				int[] predicateIndexes = IntStream.range(0, values.length)
						.filter(i -> values[i] instanceof IRI)
						.toArray();
				ValueStore.FreshValueAssignment assignment = store.assignFreshValues(session, values, predicateIndexes);
				ValueStore.FreshValueEncoder encoder = store.freshValueEncoder(session, assignment);
				ValueStore.PreparedValueBatch batch;
				while ((batch = encoder.next(2)) != null) {
					store.persistPreparedValues(batch);
				}
				publication = assignment.publication();
			}
			ids = publication.ids();
			store.commit();
			store.commitFreshValueTransaction(session);
			store.publishPreparedValues(publication);
			store.discardFreshValueSession(session);
		}
		}
		return ids;
	}

	private static void assertNoAlternativeSearch(ObservedValueStore store) {
		assertEquals(0, store.alternativeLookups, "alternative IRI searches");
		assertEquals(0, store.alternativeProbes, "native alternative-prefix probes");
		assertEquals(0, store.alternativeSeeks, "native alternative-prefix seeks");
	}

	enum WritePath {
		SCALAR,
		BATCH,
		PREPARED,
		ASSIGNED
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig().setValueOverlayEnabled(false).setInlineLiterals(false);
	}

	private static final class ObservedValueStore extends ValueStore implements AutoCloseable {
		private int alternativeLookups;
		private int alternativeProbes;
		private int alternativeSeeks;

		ObservedValueStore(File directory) throws IOException {
			super(directory, config());
		}

		@Override
		void alternativeIriLookupStarted() {
			alternativeLookups++;
		}

		@Override
		int probeIriAlternative(long txn, MDBVal key, MDBVal value) {
			alternativeProbes++;
			return super.probeIriAlternative(txn, key, value);
		}

		@Override
		int seekIriAlternative(long cursor, MDBVal key, MDBVal value, int operation) {
			alternativeSeeks++;
			return super.seekIriAlternative(cursor, key, value, operation);
		}
	}
